package bo.com.ganadero.alertas.infrastructure;
import bo.com.ganadero.alertas.application.TipoAlerta;import bo.com.ganadero.alertas.domain.*;import bo.com.ganadero.shared.error.*;import tools.jackson.core.type.TypeReference;import tools.jackson.databind.ObjectMapper;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;import java.sql.*;import java.time.Instant;import java.time.OffsetDateTime;import java.util.*;
@Repository public class JdbcAlertaRepository implements AlertaRepository{private final JdbcClient jdbc;private final ObjectMapper json;public JdbcAlertaRepository(JdbcClient j,ObjectMapper o){jdbc=j;json=o;}
 public Alerta programar(Alerta a){UUID id=jdbc.sql("insert into alertas.alertas(id,empresa_id,animal_id,tipo,titulo,mensaje,severidad,fecha_programada,fecha_vencimiento,origen_tipo,origen_id,estado,metadata,clave_idempotencia) values(:id,:e,:an,:t,:ti,:m,:s,:fp,:fv,:ot,:oi,:es,cast(:md as jsonb),:ci) on conflict(empresa_id,clave_idempotencia) do update set titulo=excluded.titulo,mensaje=excluded.mensaje,severidad=excluded.severidad,fecha_programada=excluded.fecha_programada,fecha_vencimiento=excluded.fecha_vencimiento,metadata=excluded.metadata,updated_at=now() returning id").param("id",a.id()).param("e",a.empresaId()).param("an",a.animalId()).param("t",a.tipo().name()).param("ti",a.titulo()).param("m",a.mensaje()).param("s",a.severidad().name()).param("fp",ts(a.fechaProgramada())).param("fv",ts(a.fechaVencimiento())).param("ot",a.origenTipo()).param("oi",a.origenId()).param("es",a.estado().name()).param("md",write(a.metadata())).param("ci",a.claveIdempotencia()).query(UUID.class).single();return buscar(id,a.empresaId()).orElseThrow();}
 public Optional<Alerta> evolucionarOrigen(Alerta a,Collection<TipoAlerta> anteriores){if(anteriores==null||anteriores.isEmpty())return Optional.empty();String tipos=anteriores.stream().map(t->"'"+t.name()+"'").collect(java.util.stream.Collectors.joining(","));String sql="update alertas.alertas set tipo=:t,titulo=:ti,mensaje=:m,severidad=:s,fecha_programada=:fp,fecha_vencimiento=:fv,metadata=cast(:md as jsonb),clave_idempotencia=:ci,estado=case when tipo<>:t or severidad<>:s then 'PENDIENTE' else estado end,enviada_at=case when tipo<>:t or severidad<>:s then null else enviada_at end,updated_at=now() where empresa_id=:e and origen_tipo=:ot and origen_id=:oi and tipo in ("+tipos+") and estado in('PROGRAMADA','PENDIENTE','ENVIADA','ATENDIDA','ERROR') returning id";Optional<UUID> id=jdbc.sql(sql).param("t",a.tipo().name()).param("ti",a.titulo()).param("m",a.mensaje()).param("s",a.severidad().name()).param("fp",ts(a.fechaProgramada())).param("fv",ts(a.fechaVencimiento())).param("md",write(a.metadata())).param("ci",a.claveIdempotencia()).param("e",a.empresaId()).param("ot",a.origenTipo()).param("oi",a.origenId()).query(UUID.class).optional();return id.flatMap(x->buscar(x,a.empresaId()));}
 public Optional<Alerta>buscar(UUID id,UUID e){return jdbc.sql("select * from alertas.alertas where id=:id and empresa_id=:e").param("id",id).param("e",e).query(this::map).optional();}public List<Alerta>listar(UUID e,EstadoAlerta s,TipoAlerta t,UUID a){return jdbc.sql("select * from alertas.alertas where empresa_id=:e and (cast(:s as text) is null or estado=:s) and (cast(:t as text) is null or tipo=:t) and (cast(:a as uuid) is null or animal_id=:a) order by fecha_programada desc").param("e",e).param("s",s==null?null:s.name()).param("t",t==null?null:t.name()).param("a",a).query(this::map).list();}
 public void resolverOrigen(UUID e,String o,UUID id,UUID actor){jdbc.sql("update alertas.alertas set estado='RESUELTA',resuelta_at=now(),resuelta_por=:a,updated_at=now() where empresa_id=:e and origen_tipo=:o and origen_id=:id and estado in('PROGRAMADA','PENDIENTE','ENVIADA','ATENDIDA','ERROR')").param("a",actor).param("e",e).param("o",o).param("id",id).update();}public void cancelarOrigen(UUID e,String o,UUID id,String motivo){jdbc.sql("update alertas.alertas set estado='CANCELADA',cancelada_at=now(),motivo_cancelacion=:m,updated_at=now() where empresa_id=:e and origen_tipo=:o and origen_id=:id and estado in('PROGRAMADA','PENDIENTE','ENVIADA','ATENDIDA','ERROR')").param("m",motivo).param("e",e).param("o",o).param("id",id).update();}
 public Alerta atender(UUID id,UUID e,UUID a){return cambio(id,e,a,"ATENDIDA","atendida_at","atendida_por");}public Alerta resolver(UUID id,UUID e,UUID a){return cambio(id,e,a,"RESUELTA","resuelta_at","resuelta_por");}private Alerta cambio(UUID id,UUID e,UUID a,String estado,String fecha,String actor){int n=jdbc.sql("update alertas.alertas set estado='"+estado+"',"+fecha+"=now(),"+actor+"=:a,updated_at=now() where id=:id and empresa_id=:e and estado not in('RESUELTA','CANCELADA')").param("a",a).param("id",id).param("e",e).update();if(n==0)throw new BusinessException(ErrorCode.ALERTA_NOT_FOUND);return buscar(id,e).orElseThrow();}
  public int activarVencidas(Instant now,int limite){return jdbc.sql("with candidatas as(select id from alertas.alertas where estado='PROGRAMADA' and fecha_programada<=:n order by fecha_programada for update skip locked limit :l) update alertas.alertas a set estado='PENDIENTE',updated_at=now() from candidatas c where a.id=c.id").param("n",Timestamp.from(now)).param("l",limite).update();}
 public List<Alerta>listarPendientes(Instant ahora,int limite){return jdbc.sql("select * from alertas.alertas where estado='PENDIENTE' and fecha_programada<=:n order by fecha_programada limit :l").param("n",ts(ahora)).param("l",limite).query(this::map).list();}
  public void marcarEnviada(UUID id){jdbc.sql("update alertas.alertas set estado='ENVIADA',enviada_at=coalesce(enviada_at,now()),updated_at=now() where id=:id").param("id",id).update();}
  private Alerta map(ResultSet r,int n)throws SQLException{return new Alerta(r.getObject("id",UUID.class),r.getObject("empresa_id",UUID.class),r.getObject("animal_id",UUID.class),TipoAlerta.valueOf(r.getString("tipo")),r.getString("titulo"),r.getString("mensaje"),SeveridadAlerta.valueOf(r.getString("severidad")),instant(r,"fecha_programada"),instant(r,"fecha_vencimiento"),r.getString("origen_tipo"),r.getObject("origen_id",UUID.class),EstadoAlerta.valueOf(r.getString("estado")),read(r.getString("metadata")),instant(r,"enviada_at"),instant(r,"atendida_at"),instant(r,"resuelta_at"),instant(r,"cancelada_at"),r.getObject("atendida_por",UUID.class),r.getObject("resuelta_por",UUID.class),r.getString("motivo_cancelacion"),r.getInt("intentos_envio"),r.getString("ultimo_error"),instant(r,"created_at"),instant(r,"updated_at"),r.getString("clave_idempotencia"));}private String write(Map<String,Object>m){try{return json.writeValueAsString(m==null?Map.of():m);}catch(Exception e){throw new IllegalArgumentException(e);}}private Map<String,Object>read(String s){try{return json.readValue(s,new TypeReference<>(){});}catch(Exception e){return Map.of();}} private static Instant instant(ResultSet r,String c)throws SQLException{OffsetDateTime v=r.getObject(c,OffsetDateTime.class);return v==null?null:v.toInstant();}private static Timestamp ts(Instant i){return i==null?null:Timestamp.from(i);}
}
